export const CHECKS=['Approved sample','Lab tests','Carton / packing','Drop test','Price / barcode','Hang tags','Labels','Composition','Metal detection'];
export const DEFECTS=['Broken stitches','Untrimmed thread','Dirty marks','Shade variation','Label placement','Open seam','Needle damage','Incorrect packing'];
export const LOCATIONS=['Front panel','Back panel','Collar / neckline','Armhole','Side seam','Waistband','Pocket','Hem','Label','Carton'];
export const defaultSetup=()=>({sop:'DEMO-FIN-SOP-R01',plan:'DEMO-PLAN-125-R01',level:'General II · normal single',letter:'K',sample:125,measurementTarget:5,minorAql:'Demo 0-accept',majorAql:'1.5',criticalAql:'0-accept',minorAc:0,majorAc:5,criticalAc:0,revision:1});
export function makeDraft(order=ORDERS[0],parent=null){return {order:order.id,stage:order.stage,kind:parent?'Reinspection':'First inspection',parent:parent?.id||null,date:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Phnom_Penh'}),line:order.line,cartons:order.cartons,inspector:'',checked:'',checks:Object.fromEntries(CHECKS.map(k=>[k,'Pending'])),findings:[],measurements:[],evidence:'',notes:'',holdLocation:'',holdQty:'',planConfirmed:false};}
export function counts(d){const rank={Minor:1,Major:2,Critical:3},pieces={};d.findings.forEach(f=>{if(!pieces[f.piece]||rank[f.severity]>rank[pieces[f.piece]])pieces[f.piece]=f.severity;});return {Minor:Object.values(pieces).filter(v=>v==='Minor').length,Major:Object.values(pieces).filter(v=>v==='Major').length,Critical:Object.values(pieces).filter(v=>v==='Critical').length,total:Object.keys(pieces).length,events:d.findings.length};}
export function assess(d,setup){
 const c=counts(d),reasons=[],pending=[];const order=ORDERS.find(o=>o.id===d.order);const checked=Number(d.checked);
 if(c.Minor>Number(setup.minorAc)||c.Major>Number(setup.majorAc)||c.Critical>Number(setup.criticalAc))reasons.push('Defective-piece acceptance limit exceeded.');
 if(d.measurements.some(m=>Math.abs(m.actual-m.spec)>m.tol+1e-8))reasons.push('Measurement outside buyer tolerance.');
 if(Object.values(d.checks).includes('Non-conform'))reasons.push('Non-conforming checklist result.');
 if(!Number.isInteger(checked)||checked<Number(setup.sample)||checked>order.quantity)pending.push('Complete the configured sample within the order quantity.');
 if(!d.planConfirmed)pending.push('Confirm the effective sampling plan and lot scope.');
 if(Object.values(d.checks).includes('Pending'))pending.push('Complete every checklist result, including justified N/A.');
 if(order.points.some(([point])=>!d.measurements.some(m=>m.point===point)))pending.push('Complete every required point in the demo buyer measurement master.');
 if(d.measurements.length<Number(setup.measurementTarget))pending.push(`Record at least ${setup.measurementTarget} planned measurement readings.`);
 if(!d.evidence.trim())pending.push('Add inspection evidence / report references.');
 if(Object.values(d.checks).includes('N/A')&&!d.notes.trim())pending.push('Explain N/A checks in notes.');
 return {technical:reasons.length?'FAIL':pending.length?'PENDING':'PASS',reasons:[...reasons,...pending],counts:c,measurement:d.measurements.length?(d.measurements.some(m=>Math.abs(m.actual-m.spec)>m.tol+1e-8)?'FAIL':'PASS'):'PENDING',defect:c.Minor>setup.minorAc||c.Major>setup.majorAc||c.Critical>setup.criticalAc?'FAIL':checked>=setup.sample?'PASS':'PENDING'};
}
export function initialData(){const setup=defaultSetup();const first=makeDraft();first.checked=125;first.planConfirmed=true;first.inspector='Demo inspector';first.checks=Object.fromEntries(CHECKS.map(k=>[k,'Conform']));first.evidence='DEMO-EVIDENCE-101';first.measurements=ORDERS[0].points.map(([point,spec,tol],i)=>({point,spec,tol,actual:spec,size:'M',piece:i+1,unit:'in'}));first.findings=[{piece:1,severity:'Major',code:'Broken stitches',location:'Armhole'},{piece:2,severity:'Major',code:'Broken stitches',location:'Front panel'},{piece:3,severity:'Major',code:'Dirty marks',location:'Side seam'},{piece:4,severity:'Major',code:'Untrimmed thread',location:'Collar / neckline'}];const second=makeDraft(ORDERS[1]);second.checked=125;second.planConfirmed=true;second.inspector='Demo inspector';second.checks={...first.checks,'Carton / packing':'N/A','Drop test':'N/A','Price / barcode':'N/A','Hang tags':'N/A'};second.notes='Inline stage: retail packing checks do not apply; failed seat measurement held for correction.';second.evidence='DEMO-MEASURE-102';second.holdQty=125;second.holdLocation='Line 27 · hold rack';second.measurements=ORDERS[1].points.slice(0,5).map(([point,spec,tol],i)=>({point,spec,tol,actual:spec+(i===1?0.5:0),size:'M',piece:1,unit:'in'}));return {setup,custom:[],records:[{...first,id:'FIN-DEMO-001',at:Date.now()-86400000,setup:{...setup},status:'REVIEW REQUIRED',demo:true},{...second,id:'FIN-DEMO-002',at:Date.now()-3600000,setup:{...setup},status:'HOLD',demo:true}],events:[]};}

// Illustrative size grading, tied to this demo order master, not buyer standards.
export function specFor(order,point,size){const offset=['2XS','XS','S','M','L','XL','XXL'].indexOf(size)-3;const grade=order.product==='T-Shirt'?({'Chest width':1,'Body length':0.5,'Shoulder width':0.5,'Sleeve length':0.25,'Neck width':0.125}[point[0]]||0):({'Waist relaxed':1,'Seat width':1,'Thigh width':0.5,'Leg opening':0.25,'Inseam':0.5,'Side seam':1,'Front rise':0.5,'Back rise':0.5,'Waist stretched':1}[point[0]]||0);return point[1]+offset*grade;}
